  var isoLocal = now.getFullYear() + '-' + ('0' + (now.getMonth() + 1)).slice(-2) + '-' + ('0' + now.getDate()).slice(-2);
  var llmContext = (business ? 'Business: ' + business + '\n' : '')
    + 'Open follow-up task: ' + String(ta2.summary || '') + '\n'
    + (apptA
      ? 'Current appointment request: ' + String(apptA.service || 'Appointment') + ' on ' + String(apptA.date || '?') + (String(apptA.time || '') ? ' at ' + String(apptA.time) : '') + ' (status: ' + String(apptA.status || 'requested') + ')\n'
      : 'No appointment exists yet - the customer still needs to pick a day and time.\n')
    + '\nSMS conversation so far (oldest first):\n' + lines.join('\n')
    + '\n\nThe customer\'s NEW message (respond to this): "' + body + '"';
  return {
    verdict: verdict,
    hasTask: true,
    taskId: task.id,
    taskCallId: callId,
    taskCustomer: String(ta2.customer_link || ''),
    exchanges: exchanges,
    apptId: appt ? appt.id : null,
    apptDate: apptA ? String(apptA.date || '') : '',
    apptTime: apptA ? String(apptA.time || '') : '',
    apptService: apptA ? String(apptA.service || 'Appointment') : '',
    business: business,
    model: model,
    today: now.toDateString() + ' (' + isoLocal + ')',
    llmContext: llmContext,
    phone: from
  };
})()

data.prompt:
Today is {{nodes.ctx.today}}.

{{nodes.ctx.llmContext}}

Return ONLY this JSON:
{"action": "confirm" | "reschedule" | "cancel" | "ask" | "handoff", "date": "YYYY-MM-DD" or null, "time": "HH:MM" or null, "service": string or null, "reply": "one short friendly SMS (under 300 characters, plain text, no emoji)"}

Rules: "confirm" only when the customer clearly agrees to the CURRENT slot; "reschedule" when they propose a different day/time — resolve relative dates ("next Tuesday", "tomorrow") from today's date and use 24-hour time; "cancel" only when they clearly no longer want the booking; "ask" when you need one clarifying detail (your reply is the question); "handoff" for anything else — complaints, other requests, or anything unclear. Never invent prices, opening hours or services; never promise anything except booking changes; use null when unsure — never guess.

